update public.master_catalog_parameters p set clinical_metadata=coalesce(p.clinical_metadata,'{}'::jsonb)||jsonb_build_object('pediatric_interval_note','Mayo-derived pediatric intervals; use only when exact age and sex are known; local verification remains mandatory.') from public.master_catalog_tests t where p.master_test_id=t.id and t.master_code='HEM_CBC' and t.release_id=(select id from public.master_catalog_releases where version='taiba-core-2026.11.20-r1') and p.parameter_code in ('RBC','HGB','HCT','MCV','RDW_CV','WBC','PLT');

update public.master_catalog_parameters p
set clinical_metadata=coalesce(p.clinical_metadata,'{}'::jsonb)||jsonb_build_object(
  'pediatric_reference_interval_note',
  'Mayo Clinic Laboratories pediatric age/sex intervals are external comparison suggestions only. Verify the tenant analyzer, reagent, method and population before enabling local flags.'
)
from public.master_catalog_tests t
where p.master_test_id=t.id
  and t.master_code='HEM_CBC'
  and p.parameter_code in ('RBC','HGB','HCT','MCV','RDW_CV','WBC','PLT')
  and exists (
    select 1 from jsonb_array_elements(coalesce(p.reference_ranges,'[]'::jsonb)) r
    where r->>'population'='pediatric'
  );
